  var MIN = 11.5;
  for (i4 = 1; i4 < garis.length; i4++) if (garis[i4].ty - garis[i4 - 1].ty < MIN) garis[i4].ty = garis[i4 - 1].ty + MIN;
  var luber = garis.length ? garis[garis.length - 1].ty - (PADT + Hp) : 0;
