  const last = o[n - 1];
  s += `<text class="ax ow-rd-t" x="${W - PADR}" y="${(y(last.rd) - 4).toFixed(1)}" text-anchor="end">reksa dana ${last.rd.toFixed(1)}%</text>`;
  s += '</svg>';
  // PANEL PERUBAHAN — tumpukan 100% menyembunyikan gerak 0,3 poin yang justru jadi sinyal; di sini
